"""Convert SPDX v2.3 json files generated by buildstream-sbom to md.

Usage:
    python3 jsontomd.py manifest.spdx.json

This will produce a manifest.md in the same directory as the manifest.spdx.json
"""

import argparse
import json
import logging
import os
from pathlib import Path

logging.basicConfig(level=os.environ.get("LOGLEVEL", "INFO").upper())
logger = logging.getLogger()

parser = argparse.ArgumentParser(description="Process input file")

parser.add_argument("json", help="A json file to convert to Markdown")

args = parser.parse_args()


""" Sample input data for reference:
"packages": [
    {
    "name": "acl",
    "SPDXID": "SPDXRef-bootstrap-acl.bst",
    "filesAnalyzed": false,
    "downloadLocation": "NOASSERTION",
    "externalRefs": [
        {
        "referenceCategory": "OTHER",
        "referenceType": "bst-element",
        "referenceLocator": "bootstrap/acl.bst"
        }
    ]
    },
    {
    "SPDXID": "SPDXRef-bootstrap-acl.bst-0",
    "filesAnalyzed": false,
    "name": "acl",
    "downloadLocation": "https://git.savannah.gnu.org/git/acl.git",
    "versionInfo": "2.3.2",
    "sourceInfo": "git_repo",
    "externalRefs": [
        {
        "referenceCategory": "OTHER",
        "referenceType": "bst-element",
        "referenceLocator": "bootstrap/acl.bst"
        }
    ]
    },
    ...
]
"""

json_data = json.loads(Path(args.json).read_text(encoding="utf-8"))
dst = Path(args.json).parent / Path(args.json).name.replace("spdx.json", "md")

with dst.open("w+", encoding="utf-8") as md_file:
    current_element = None
    done_current_element = False

    for pkg in json_data["packages"]:
        spdx_id = pkg["SPDXID"]

        name = next(
            (
                pkg["referenceLocator"]
                for pkg in pkg.get("externalRefs", [])
                if pkg.get("referenceType", "") == "bst-element"
            ),
            None,
        )

        if spdx_id.endswith(".bst"):
            if current_element is not None:
                print(file=md_file)
                if not done_current_element:
                    logger.info(f"Element '{current_element}' has no sources")

            print(f"## {name}", file=md_file)

            done_current_element = False
            current_element = name
            # Package corresponding to element (rather than source)
            continue

        done_current_element = True

        if name is None:
            logger.warning(f"Skipping package {spdx_id}, missing element")
            continue

        if name != current_element:
            current_element = name
            logger.error(f"Source package '{spdx_id}' missing element package")
            continue

        if pkg["sourceInfo"] in ("tar", "git_repo", "cargo2"):
            md_file.write(f"  - {pkg['downloadLocation']}\n")

        if pkg["sourceInfo"] == "git_repo":
            md_file.write(f"  - {pkg['versionInfo']}\n")

    md_file.write("\n")
